import{_ as t,o as a,c as i,a9 as r}from"./chunks/framework.asyjyako.js";const g=JSON.parse('{"title":"Extensions and providers","description":"","frontmatter":{},"headers":[],"relativePath":"reference/extensions.md","filePath":"reference/extensions.md","lastUpdated":null}'),n={name:"reference/extensions.md"};function s(o,e,l,d,p,h){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="Extensions-and-providers" tabindex="-1">Extensions and providers <a class="header-anchor" href="#Extensions-and-providers" aria-label="Permalink to &quot;Extensions and providers {#Extensions-and-providers}&quot;">​</a></h1><p>PerfChecker separates interface packages, small API extensions and diagnostic worker providers. See <a href="./../interfaces/packages">interface packages</a> for installation.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Extension</th><th style="text-align:right;">Activated by</th><th style="text-align:right;">Capability</th></tr></thead><tbody><tr><td style="text-align:right;">BenchmarkToolsExt</td><td style="text-align:right;">BenchmarkTools</td><td style="text-align:right;"><code>:benchmark</code> collector</td></tr><tr><td style="text-align:right;">ChairmarksExt</td><td style="text-align:right;">Chairmarks</td><td style="text-align:right;"><code>:chairmark</code> collector</td></tr><tr><td style="text-align:right;">DrWatsonExt</td><td style="text-align:right;">DrWatson</td><td style="text-align:right;">parameter naming, cached production, suite runs</td></tr><tr><td style="text-align:right;">DocumenterExt</td><td style="text-align:right;">Documenter</td><td style="text-align:right;">generated performance pages and docs builds</td></tr><tr><td style="text-align:right;">DocumenterVitepressExt</td><td style="text-align:right;">Documenter + DocumenterVitepress</td><td style="text-align:right;">VitePress-aware docs build</td></tr><tr><td style="text-align:right;">UnicodePlotsExt</td><td style="text-align:right;">UnicodePlots</td><td style="text-align:right;">terminal plots</td></tr><tr><td style="text-align:right;">PProfExt</td><td style="text-align:right;">FlameGraphs + PProf</td><td style="text-align:right;">pprof/folded/speedscope profile artifacts</td></tr><tr><td style="text-align:right;">PropCheckExt</td><td style="text-align:right;">PropCheck</td><td style="text-align:right;">reproducible property corpus freezing</td></tr><tr><td style="text-align:right;">SuppositionExt</td><td style="text-align:right;">Supposition</td><td style="text-align:right;">reproducible property corpus freezing</td></tr><tr><td style="text-align:right;">TestItemRunnerExt</td><td style="text-align:right;">TestItemRunner &gt;= 1.3.2</td><td style="text-align:right;">native item discovery and whole-item measurement</td></tr><tr><td style="text-align:right;">HTTPAdvisorExt</td><td style="text-align:right;">HTTP</td><td style="text-align:right;">optional advisor transport</td></tr></tbody></table><p>Add optional packages to the <strong>controller</strong> environment that needs them. A renderer does not become a measured-worker dependency. Collector packages are loaded in the target worker only when that backend requires them.</p><h2 id="Version-compatibility" tabindex="-1">Version compatibility <a class="header-anchor" href="#Version-compatibility" aria-label="Permalink to &quot;Version compatibility {#Version-compatibility}&quot;">​</a></h2><p>Interface and analyzer compatibility belongs to the component that uses the package. The core no longer declares Oxygen, Pluto, Makie, WGLMakie, Bonito, JET, AllocCheck or SnoopCompile as optional dependencies. Aqua remains a core quality-test dependency, not a diagnostic extension.</p><p><code>PerfCheckerMakie</code> owns the optional WGLMakie/Bonito rendering extension. Tool adapters and their Project.toml files live under <code>providers/</code>. Their availability is checked in the diagnostic worker, without importing the controller there.</p><p>The following upstream releases were inspected on 12 September 2026. These are compatibility facts, not a claim that all combinations passed collection tests. The publication inventory records actual versions for each qualified environment.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Stack</th><th style="text-align:right;">Current releases</th><th style="text-align:right;">Constraint</th></tr></thead><tbody><tr><td style="text-align:right;">Web and interactive plots</td><td style="text-align:right;">Oxygen 1.11.0, HTTP 2.6.7, Bonito 5.2.0, Makie 0.24.14, WGLMakie 0.13.14</td><td style="text-align:right;">Julia &gt;= 1.11; no Pluto 1.0.3 in this environment</td></tr><tr><td style="text-align:right;">Notebook</td><td style="text-align:right;">Pluto 1.0.3</td><td style="text-align:right;">HTTP 1; use a separate environment from the latest web stack</td></tr><tr><td style="text-align:right;">Julia 1.10 web</td><td style="text-align:right;">Oxygen 1.10.2, HTTP 1.11.0</td><td style="text-align:right;">Compatible fallback for the minimum Julia version</td></tr><tr><td style="text-align:right;">Inference analysis</td><td style="text-align:right;">JET 0.12.1</td><td style="text-align:right;">Julia &gt;= 1.12; older JET lines remain admitted</td></tr></tbody></table><p>The HTTP.jl 2 migration is already in the tagged <a href="https://github.com/OxygenFramework/Oxygen.jl/releases/tag/v1.11.0" target="_blank" rel="noreferrer">Oxygen 1.11.0 release</a>, published 28 August 2026. The checked master revision is identical to that tag. Its <a href="https://github.com/OxygenFramework/Oxygen.jl/blob/v1.11.0/Project.toml" target="_blank" rel="noreferrer">Project.toml</a> requires HTTP &gt;= 2.4 and Julia &gt;= 1.11. There is no pending master-only correction to adopt. <a href="https://github.com/fonsp/Pluto.jl/blob/v1.0.3/Project.toml" target="_blank" rel="noreferrer">Pluto&#39;s HTTP 1 constraint</a> still prevents combining the latest notebook and web stacks.</p><p>HTTP.jl package versions 1 and 2 are dependency generations; they are distinct from the HTTP/1.1 and HTTP/2 wire protocols. PerfChecker tests its two dependency stacks separately. A resolved environment proves dependency compatibility; execution, rendering and correctness checks provide the integration evidence.</p><h2 id="DrWatson" tabindex="-1">DrWatson <a class="header-anchor" href="#DrWatson" aria-label="Permalink to &quot;DrWatson {#DrWatson}&quot;">​</a></h2><p>This example uses the <code>plan</code> built in the <a href="./../software-suites">software-suite tutorial</a>. Add DrWatson to that controller environment before loading the extension.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker, DrWatson</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">params </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> drwatson_parameters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(plan)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> drwatson_savename</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(params)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> drwatson_produce_or_load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(plan, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/results&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>drwatson_run_suite</code> combines structured experiment parameters, resumable output, and the normal PerfChecker runner. Cache reuse remains explicit in run evidence.</p><h2 id="Property-based-workloads" tabindex="-1">Property-based workloads <a class="header-anchor" href="#Property-based-workloads" aria-label="Permalink to &quot;Property-based workloads {#Property-based-workloads}&quot;">​</a></h2><p>PropCheck and Supposition adapters freeze minimized/counterexample inputs into a portable corpus. This makes a stochastic discovery reproducible before it becomes a performance fixture. Corpus generation is not mixed into benchmark sampling; measure the frozen examples in a separate deterministic run.</p><h2 id="Add-a-Julia-backend" tabindex="-1">Add a Julia backend <a class="header-anchor" href="#Add-a-Julia-backend" aria-label="Permalink to &quot;Add a Julia backend {#Add-a-Julia-backend}&quot;">​</a></h2><p>A backend implements the hook surface for its <code>Val{:backend}</code>:</p><ul><li><p><code>initpkgs</code> loads required packages in the worker;</p></li><li><p><code>default_options</code> declares defaults;</p></li><li><p><code>prep</code> prepares fixtures;</p></li><li><p><code>check</code> performs measurement;</p></li><li><p><code>post</code> normalizes evidence;</p></li><li><p>optionally <code>cleanup</code> and <code>stop_before_post</code> manage exit-flushed artifacts.</p></li></ul><p>The backend must define versioned measurement definitions, units, preference, scope, perturbation, capability checks, deterministic fixtures, and TestItems. It should return data through the common bundle grammar before gaining UI or CI claims.</p><h2 id="Add-another-programming-setup" tabindex="-1">Add another programming setup <a class="header-anchor" href="#Add-another-programming-setup" aria-label="Permalink to &quot;Add another programming setup {#Add-another-programming-setup}&quot;">​</a></h2><p>Use <code>ExternalCommandSpec</code> and <code>perfchecker-provider-result/1</code>. Qualify each provider independently with a capability manifest and conformance suite. The shared protocol is deliberately language-neutral, while measurement semantics remain specific to the actual runtime and tools.</p>`,23)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
